// ============================================================
// FAMILYFLOW — Default Avatars (auto-set on first run)
// ============================================================

const DEFAULT_AVATARS = {
  1: 'data:image/png;base64,',
  2: 'data:image/png;base64,',
  3: 'data:image/png;base64,',
};

export function setDefaultAvatars() {
  for (const [userId, dataUrl] of Object.entries(DEFAULT_AVATARS)) {
    const key = `ff_avatar_photo_${userId}`;
    if (!localStorage.getItem(key)) {
      localStorage.setItem(key, dataUrl);
    }
  }
}

